SELECT cp.cp_department, d.d_year, SUM(cs.cs_net_paid) AS total_net_paid, (SELECT d2.d_month_seq FROM date_dim d2 WHERE d2.d_date_sk = 2415059) AS ref_month_seq FROM catalog_sales cs JOIN date_dim d ON cs.cs_sold_date_sk = d.d_date_sk JOIN catalog_page cp ON cs.cs_catalog_page_sk = cp.cp_catalog_page_sk JOIN catalog_returns cr ON cs.cs_order_number = cr.cr_order_number WHERE cp.cp_type = 'quarterly' GROUP BY cp.cp_department, d.d_year HAVING COUNT(*) > 20
